#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include "shared_game_media_download_queue.h"
#include <iostream>
using namespace ymcc::media;using namespace ymcc::media::downloads;
static int checks=0;static void check(bool ok,const char*why){++checks;if(!ok)throw std::runtime_error(why);}
static Json target(int id,int tier,const char*source,int rank=0){return{{"appId",id},{"verified",true},{"sourceTier",tier},{"catalogSource",source},{"chartRank",rank}};}
int wmain(int argc,wchar_t**argv){try{if(argc!=2)throw std::runtime_error("fresh isolated root required");const auto root=fs::absolute(argv[1]);if(fs::exists(root))throw std::runtime_error("fresh root required");fs::create_directories(root);
 Queue q(root);q.enqueue(Json::array({target(570,0,"popular",1),target(730,0,"popular",2),target(620,1,"steam-native"),target(400,1,"steam-native"),target(10,2,"ymcc-confirmed")}));const auto token=q.start();auto first=q.claim(token);check(first.value("appId",0)==570,"first free slot takes highest ranked pending popular game");auto second=q.claim(token);check(second.value("appId",0)==730,"second free slot takes next popular before native game");auto third=q.claim(token);check(third.is_object()&&third.value("sourceTier",-1)==1,"slow in-flight popular games must not idle free native download lanes");auto fourth=q.claim(token);check(fourth.is_object()&&fourth.value("sourceTier",-1)==1,"next native target can use another free lane");auto fifth=q.claim(token);check(fifth.value("appId",0)==10,"confirmed target fills remaining lane after all higher waiting targets are claimed");check(q.snapshot().value("activeCount",0)==5,"production queue reaches five mixed-priority lanes without duplicate claims");check(q.claim(token).is_null(),"already-running jobs cannot be claimed twice");q.result(token,first.value("key",std::string{}),true);q.enqueue(Json::array({target(999,0,"popular",1)}));check(q.claim(token).value("appId",0)==999,"new waiting popular work wins the next slot without killing existing local transfers");q.end(token,"completed");check(q.snapshot().value("activeCount",0)==0,"session end releases all claims");Json result={{"ok",true},{"checks",checks},{"scope","Actual durable Queue claim scheduling; isolated assets and no network/process/Steam actions"}};atomicWrite(root/L"result.json",result);std::cout<<result.dump()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
